}

// Draw fish
function drawFish(x, y, scale, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.arc(x, y, scale * 2, 0, Math.PI);
    ctx.arc(x + scale * 4, y, scale * 2, 0, Math.PI);
    ctx.arc(x + scale * 8, y, scale * 2, 0, Math.PI);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.moveTo(x - scale, y);
    ctx.arc(x - scale, y, scale * 0.5, 0, Math.PI);
    ctx.arc(x - scale + scale * 0.8, y, scale * 0.5, 0, Math.PI);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x + scale * 8, y);
    ctx.arc(x + scale * 8, y, scale * 1.5, 0, Math.PI);
    ctx.arc(x + scale * 12, y, scale * 1.5, 0, Math.PI);
    ctx.closePath();
    ctx.fill();
}

