        ctx.strokeStyle = `hsl(${180 + level * 15}, 60%, ${60 - level * 10}%)`;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + size, y);
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x, y - size);
        ctx.stroke();

        // Recursive calls for arms
        drawSpiral(x + size, y, size * 0.85, level - 1);
        drawSpiral(x, y - size, size * 0.85, level - 1);
    }
};

