// Main jellyfish form
const centerX = 200;
const centerY = 200;
const bodyRadius = 40;

// Glow effect using multiple circles
ctx.globalAlpha = 0.3;
ctx.fillStyle = 'rgba(255, 200, 100, 0.4)';
for(let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI * 2;
    const r = bodyRadius + 10 + Math.sin(i * 0.5) * 10;
    const x = centerX + Math.cos(angle) * r;
    const y = centerY + Math.sin(angle) * r;
    ctx.beginPath();
    ctx.arc(x, y, 20, 0, Math.PI * 2);
    ctx.fill();
}

// Inner glow core
ctx.globalAlpha = 0.6;
ctx.fillStyle = 'rgba(255, 180, 50, 0.6)';
ctx.beginPath();
ctx.arc(centerX, centerY, bodyRadius - 10, 0, Math.PI * 2);
ctx.fill();

// Tentacles
ctx.globalAlpha = 1;
const tentacleCount = 8;
const totalLength = 80;
const width = 4;

ctx.fillStyle = 'rgba(255, 180, 50, 0.8)';
for(let i = 0; i < tentacleCount; i++) {
    const angle = (i / tentacleCount) * Math.PI * 2 - Math.PI / 2;
    const startX = centerX + Math.cos(angle) * bodyRadius;
    const startY = centerY + Math.sin(angle) * bodyRadius;

    // Tentacle base
    ctx.beginPath();
    ctx.moveTo(startX, startY);
    ctx.lineTo(
        startX + Math.cos(angle) * totalLength,
        startY + Math.sin(angle) * totalLength
    );
    ctx.lineWidth = width;
    ctx.lineCap = 'round';
    ctx.stroke();

    // Tentacle details
    ctx.beginPath();
    ctx.moveTo(
        startX + Math.cos(angle) * totalLength * 0.8,
        startY + Math.sin(angle) * totalLength * 0.8
    );
    ctx.lineTo(
        startX + Math.cos(angle) * totalLength * 0.6,
        startY + Math.sin(angle) * totalLength * 0.6
    );
    ctx.lineWidth = width * 0.8;
    ctx.stroke();
}

